for(const id of ['kimi','gemini','deepseek','mistral','ollama','lmstudio','perplexity','meta'])providerIcons[id]=`<img src="/icons/${id}.svg" alt="" aria-hidden="true">`;
const $ = s => document.querySelector(s);
const escape = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state = {teams: [], runs: []}, connections = [], view = 'chat', selectedRun, selectedTeam, selectedAgent=0, chatMessages=[], teamChatMessages=[], teamChatRecipient=0, fieldCount = 0, loading = false;
const labels = { completed:'Completado', running:'Trabajando', queued:'En espera', failed:'Necesita atención', cancelled:'Cancelado', interrupted:'Interrumpido', waiting:'Esperando aprobación' };
function notice(message = '') { $('#notice').textContent = message; }
async function api(path, body) {
  const r = await fetch(`/api/${path}`, body === undefined ? {} : {method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});
  const data = await r.json(); if (!r.ok) throw new Error(data.error || 'No se pudo completar la acción.'); return data;
}
async function refresh() { state = await api('state'); if (view !== 'task') render(); }
function heading(title, text, button='') { return `<div class="heading"><div><div class="eyebrow">AGENTES QUE TRABAJAN EN EQUIPO</div><h1>${title}</h1><div class="muted">${text}</div></div>${button}</div>`; }
function providerName(id) { return connections.find(p => p.id === id)?.name || id; }
function connectedProviders(){return connections.filter(p=>p.id!=='demo'&&p.installed&&p.supported!==false&&p.accountState==='connected');}
function providerOptions(current=''){
 const available=connectedProviders();
 const existing=current&&!available.some(p=>p.id===current)?connections.find(p=>p.id===current):null;
 const options=available.map(p=>`<option value="${escape(p.id)}" ${p.id===current?'selected':''}>${escape(p.name)}</option>`).join('');
 const saved=existing?`<option value="${escape(existing.id)}" selected>${escape(existing.name)} · asignado previamente</option>`:'';
 return saved+options||'<option value="" selected disabled>Ninguna cuenta conectada</option>';
}

const avatarGroups={personajes:'Personajes',formas:'Formas',lapiz:'Trazo lápiz',garabatos:'Garabatos'};
const characterNames=['Lupa','Tinta','Datos','Bit','Rumbo','Búho','Zorro','Pulpo','Eco','Rey','Musa','Agenda'];
const shapeNames=['Ojos punto · burbuja','Ojos punto · cuadrado','Ojos punto · tarjeta','Feliz · burbuja','Ojos altos · cuadrado','Guiño · tarjeta','Guiño · burbuja','Dormido · cuadrado','Feliz · tarjeta','Ojos altos · burbuja','Ojos grandes · cuadrado','Dormido · tarjeta'];
const validAvatar=id=>/^(formas|lapiz|garabatos|personajes)-(?:[0-9]|1[01])$/.test(id||'');
function animatedAgent(a,status){return window.tropaAnimation(a,status);}
function avatarName(id){const [g,n]=id.split('-');return (g==='personajes'?characterNames:shapeNames)[Number(n)]||'Avatar';}
function agentAvatar(a){return validAvatar(a?.avatar)?`<span class="art-avatar art-${a.avatar}" role="img" aria-label="${escape(avatarName(a.avatar))}"></span>`:`<span class="avatar">${escape(a?.name?.slice(0,1)||'•')}</span>`;}
function avatarGrid(group,selected){return Array.from({length:12},(_,i)=>{const id=group+'-'+i;return `<button type="button" data-art-avatar="${id}" aria-label="Elegir ${escape(avatarName(id))}" aria-pressed="${id===selected}">${agentAvatar({avatar:id})}<span>${escape(avatarName(id))}</span></button>`;}).join('');}
function avatarLibrary(){return `<div class="avatar-library"><div class="avatar-art-preview">${agentAvatar({avatar:'personajes-0'})}</div><input type="hidden" name="avatar" value="personajes-0"><label>Colección de avatares<select id="avatar-collection">${Object.entries(avatarGroups).map(([id,name])=>`<option value="${id}">${name}</option>`).join('')}</select></label><div class="art-grid">${avatarGrid('personajes','personajes-0')}</div></div>`;}
const agentPresets={
 lupa:{name:'Lupa',role:'Investigador',avatar:'personajes-0',description:'Busca, compara y resume fuentes con contexto.',instructions:'Investigá las preguntas y los materiales que te comparta la persona. Compará fuentes, distinguí hechos de hipótesis y citá las fuentes consultadas. Indicá qué datos faltan y resumí los hallazgos con claridad.'},
 tinta:{name:'Tinta',role:'Redactor',avatar:'personajes-1',description:'Redacta correos, propuestas y publicaciones.',instructions:'Redactá y mejorá correos, propuestas y publicaciones según el objetivo y el tono que indique la persona. Pedí los datos que falten, revisá claridad y ortografía, y entregá textos listos para revisar.'},
 datos:{name:'Datos',role:'Analista',avatar:'personajes-2',description:'Analiza datos y explica cambios y hallazgos.',instructions:'Analizá los datos y archivos que te proporcionen. Comprobá cálculos, identificá tendencias y anomalías, y explicá tus conclusiones y sus límites. No inventes datos ni afirmes haber leído archivos que no consultaste.'},
 bit:{name:'Bit',role:'Desarrollador',avatar:'personajes-3',description:'Revisa código y ayuda a automatizar tareas.',instructions:'Ayudá a revisar código, investigar errores y diseñar soluciones y automatizaciones. Explicá los cambios propuestos y las verificaciones realizadas. Trabajá solo con los archivos y herramientas que tengas habilitados.'},
 eco:{name:'Eco',role:'Soporte',avatar:'personajes-8',description:'Prepara respuestas y detecta consultas importantes.',instructions:'Ayudá a atender consultas de clientes con respuestas claras y amables. Usá únicamente la información disponible, señalá los casos que necesitan atención humana y prepará respuestas para revisión. No afirmes haber enviado mensajes si no ocurrió.'},
 agenda:{name:'Agenda',role:'Planificador',avatar:'personajes-11',description:'Organiza tareas, plazos y próximos pasos.',instructions:'Organizá objetivos en tareas, prioridades, responsables y plazos cuando estén disponibles. Señalá dependencias y datos faltantes, y prepará un plan fácil de seguir. No afirmes haber creado recordatorios o eventos sin hacerlo.'}
};
function presetCards(){return `<section class="agent-presets"><div class="agent-presets-heading"><div><h2>Empezá con un agente prearmado</h2><p>Elegí un perfil y personalizalo antes de crearlo.</p></div><span class="tiny">O creá el tuyo desde cero</span></div><div class="preset-grid">${Object.entries(agentPresets).map(([id,p])=>`<button type="button" data-preset="${id}" aria-pressed="false">${agentAvatar({avatar:p.avatar})}<span><strong>${p.name} <small>${p.role}</small></strong><span>${p.description}</span></span></button>`).join('')}</div></section>`;}
function agentAvatarChoice(){return `<label>Avatar del agente<div class="agent-avatar-choice"><span class="agent-avatar-preview">${agentAvatar({avatar:'personajes-0'})}</span><select name="avatar">${Object.entries(avatarGroups).map(([g,label])=>`<optgroup label="${label}">${Array.from({length:12},(_,i)=>`<option value="${g}-${i}">${avatarName(g+'-'+i)}</option>`).join('')}</optgroup>`).join('')}</select></div></label>`;}

function teamAvatar(id) {
  const first=state.teams.find(t=>t.id===id)?.agents[0];if(validAvatar(first?.avatar))return agentAvatar(first);
  let a = {}; try { a = JSON.parse(localStorage.getItem('appearance-'+id)) || {}; } catch {}
  const color = ['purple','red','orange','yellow','green','mint','teal','cyan','blue','indigo','pink','rose'].includes(a.color) ? a.color : 'purple';
  const shape = ['round','square','diamond'].includes(a.shape) ? a.shape : 'round';
  return `<span class="saved-avatar ${color}"><span class="mini-bot ${shape}">${escape(a.symbol||'••')}</span></span>`;
}
const collapsedTeams=new Set();
function filterSidebar() {
  const query=$('#sidebar-search').value.trim().toLocaleLowerCase();
  document.querySelectorAll('.sidebar-team').forEach(group=>{
    const teamMatches=group.dataset.teamName.toLocaleLowerCase().includes(query);
    let visible=0;
    group.querySelectorAll('.agent-sidebar').forEach(el=>{el.hidden=!!query&&!teamMatches&&!el.textContent.toLocaleLowerCase().includes(query);if(!el.hidden)visible++;});
    group.hidden=!!query&&!teamMatches&&!visible;
    group.open=!!query||!collapsedTeams.has(group.dataset.teamId);
  });
}
document.addEventListener('toggle',e=>{const group=e.target;if(!group.matches?.('.sidebar-team')||$('#sidebar-search').value.trim())return;group.open?collapsedTeams.delete(group.dataset.teamId):collapsedTeams.add(group.dataset.teamId);},true);
function render() {
  document.querySelectorAll('[data-view].active').forEach(el=>el.classList.remove('active')); $(`[data-view="${view === 'task' ? 'teams' : view}"]`)?.classList.add('active');
  $('#breadcrumb').textContent = {teams:'Mis equipos',runs:'Conversaciones',internal:'Navegador interno',connectors:'Conectores',whatsapp:'WhatsApp',updates:'Actualizaciones',providers:'Conexiones',task:'Nuevo objetivo',create:'Nuevo agente',chat:'Chat con agente',teamchat:'Chat de equipo',routines:'Rutinas',workflows:'Flujos de trabajo',tasks:'Tareas',schedules:'Programación'}[view];
  $('#sidebar-items').innerHTML = `<div class="sidebar-heading"><span class="nav-label">EQUIPOS Y AGENTES</span><button class="quiet" data-action="new" aria-label="Crear equipo" title="Crear equipo">＋</button></div>${[...state.teams].sort((a,b)=>(b.id===state.mainTeamId)-(a.id===state.mainTeamId)).map(t=>`<details class="sidebar-team" data-team-id="${t.id}" data-team-name="${escape(t.name)}" ${collapsedTeams.has(t.id)?'':'open'}><summary><span class="team-chevron" aria-hidden="true">›</span><strong>${escape(t.name)}${t.id===state.mainTeamId?' · Coordinador':''}</strong><span class="team-count">${t.agents.length}</span></summary><div class="team-members">${t.agents.map((a,i)=>`<button class="sidebar-item agent-sidebar ${view==='chat'&&selectedTeam===t.id&&selectedAgent===i?'selected':''}" data-chat-team="${t.id}" data-chat-agent="${i}">${agentAvatar(a)}<span><strong>${escape(a.name)}</strong><small>${escape(providerName(a.provider))}</small></span></button>`).join('')}${t.id!==state.mainTeamId?`<button class="team-task" data-team-chat="${t.id}">◉ Chat de equipo</button><button class="team-task" data-task="${t.id}">＋ Asignar trabajo al equipo</button>`:''}</div></details>`).join('') || '<p class="sidebar-empty">Creá un agente o equipo para empezar.</p>'}`;
  renderAccounts();
  filterSidebar();
  if (renderOperations()) return;
  if (view === 'create') {
    $('#content').innerHTML = `<div class="creation-page">${presetCards()}<form id="create-agent-form">${avatarLibrary()}<div class="avatar-preview"><span class="bot-face">••</span></div><div class="color-picker" aria-label="Color del agente">${['purple','red','orange','yellow','green','mint','teal','cyan','blue','indigo','pink','rose'].map((c,i)=>`<button type="button" class="color-dot ${c} ${i===0?'chosen':''}" data-color="${c}" aria-label="Color ${c}" aria-pressed="${i===0}"></button>`).join('')}</div><div class="shape-picker" aria-label="Forma del avatar">${['round','square','diamond'].map((c,i)=>`<button type="button" class="shape-choice ${i===0?'chosen':''}" data-shape="${c}" aria-label="Avatar ${c}" aria-pressed="${i===0}"><span class="mini-bot ${c}">••</span></button>`).join('')}</div><div class="avatar-symbols" aria-label="Estilo de avatar">${[['••','Robot'],['◈','Cristal'],['⌘','Circuito'],['🦉','Búho'],['🦊','Zorro'],['🐙','Pulpo'],['🔎','Lupa'],['🧭','Brújula'],['✒','Pluma']].map(([symbol,name])=>`<button type="button" data-symbol="${symbol}" aria-label="${name}" title="${name}">${symbol}</button>`).join('')}</div><label>Nombre <span class="required">*</span><input name="name" maxlength="80" placeholder="Nuevo agente" required></label><label>¿En qué debe ayudarte este agente?<textarea name="instructions" maxlength="2000" placeholder="Planificar proyectos, comparar opciones o ayudar con el trabajo diario." required></textarea></label><div class="model-row"><label for="agent-provider">Cuenta</label><select id="agent-provider" name="provider" required>${providerOptions()}</select></div><details class="model-details"><summary>Modelo e instrucciones de conexión</summary><input name="model" aria-label="Modelo opcional" placeholder="Modelo del proveedor (opcional)" list="local-models"><datalist id="local-models"></datalist><p class="provider-note">Vacío: se usa el modelo configurado o el primer modelo local disponible. Podés comprobar el estado de sesión en Conexiones.</p></details><label class="tools-choice"><input type="checkbox" name="tools"> Búsqueda web y archivos compartidos (GPT / Claude)</label><label class="tools-choice"><input type="checkbox" name="browser"> Navegador visual: páginas, clics y formularios</label><button class="primary create-submit">Crear agente</button><p class="creation-error" role="alert"></p></form></div>`;
    syncLocalProvider($('#agent-provider'));
  }
  if(view==='chat') {
    const t=state.teams.find(t=>t.id===selectedTeam), a=t?.agents[selectedAgent];
    if(!a){$('#content').innerHTML='<div class="welcome"><span class="welcome-symbol">✦</span><h1>Tu espacio para conversar</h1><p class="muted">Creá un agente y empezá a trabajar con él.</p><button class="primary" data-view="create">＋ Crear agente</button></div>';return;}
    const busy=chatMessages.some(r=>['running','queued'].includes(r.status));
    const last=chatMessages.at(-1), avatarStatus=busy?'running':last&&['failed','interrupted'].includes(last.status)?'failed':'idle';
    $('#content').innerHTML=`<div class="conversation agent-chat"><div class="conversation-head chat-agent-head"><div class="chat-agent-identity">${animatedAgent(a,avatarStatus)}<strong>${escape(a.name)}</strong><p class="tiny">${escape(providerName(a.provider))} · conversación individual</p></div><div><button class="quiet" data-team-edit="${t.id}">Editar ${t.id===state.mainTeamId?'agente principal':'equipo y agentes'}</button>${t.id!==state.mainTeamId?`<button class="quiet" data-delete-agent="${t.id}" data-agent-index="${selectedAgent}">Eliminar agente</button>`:''}<button class="secondary chat-team-action" data-task="${t.id}">Asignar trabajo al equipo</button></div></div>${last&&['running','queued'].includes(last.status)&&(last.source?.participants||[]).some(p=>p.agent.browser)?`<section class="browser-panel" id="run-browser" data-browser-run="${last.id}"><p class="tiny">Navegador del agente</p></section>`:''}<div class="messages">${chatMessages.map(r=>`<article class="message user-message"><div class="message-author"><span class="avatar">T</span><strong>Vos</strong></div><div class="message-body">${escape(r.source.message)}</div></article>${r.steps.map(step=>`<article class="message"><div class="message-author">${agentAvatar((r.source?.participants||[]).find(p=>p.agent.name===step.agent)?.agent||{name:step.agent})}<strong>${escape(step.agent)}</strong>${step.target?`<span class="tiny">→ ${escape(step.target)}${step.kind==='delegation'?' · consulta':''}</span>`:''}</div><div class="message-body">${escape(step.output)}</div></article>`).join('')}${r.partial?.output?`<article class="message"><div class="message-author"><strong>${escape(r.partial.agent)}</strong></div><div class="message-body">${escape(r.partial.output)}</div></article>`:''}${r.error?`<p class="error">${escape(r.error)} ${['failed','interrupted','cancelled'].includes(r.status)?`<button class="quiet" data-resume-chat="${r.id}">Continuar</button>`:''}</p>`:''}${['running','queued'].includes(r.status)?`<div class="agent-activity"><span>${escape(r.currentAgent||a.name)} está trabajando… <button class="quiet" data-cancel-chat="${r.id}">Detener</button></span></div>`:''}`).join('')||'<p class="muted">Escribile a tu agente para empezar.</p>'}</div><form id="agent-chat-form" class="chat-compose"><label class="sr-only" for="chat-input">Tu mensaje</label><textarea id="chat-input" name="message" maxlength="4000" required placeholder="Escribile a ${escape(a.name)}…" ${busy?'disabled':''}></textarea><button class="primary" ${busy?'disabled':''}>Enviar</button><p class="tiny">Se envía el historial reciente al proveedor de este agente.</p></form></div>`;
    if(last&&['running','queued'].includes(last.status)&&(last.source?.participants||[]).some(p=>p.agent.browser))loadBrowser(last.id);
  }
  if(view==='teamchat'){
    const team=state.teams.find(t=>t.id===selectedTeam),main=team?.agents[teamChatRecipient]||team?.agents[0];
    if(!team||!main){$('#content').innerHTML='<div class="empty">Equipo o coordinador no disponible.</div>';return;}
    const activeRun=teamChatMessages.find(r=>['queued','running'].includes(r.status));
    const busy=teamChatMessages.some(r=>['running','queued'].includes(r.status));
    $('#content').innerHTML=`<div class="conversation agent-chat"><div class="conversation-head"><div><h2>${escape(team.name)}</h2><span class="tiny">Elegí a quién escribirle · hasta 6 consultas por mensaje</span></div><button class="secondary" data-task="${team.id}">Objetivo secuencial</button></div>${activeRun&&(activeRun.source?.participants||[]).some(p=>p.agent.browser)?`<section class="browser-panel" id="run-browser" data-browser-run="${activeRun.id}"><p class="tiny">Navegador del agente</p></section>`:''}<div class="messages">${teamChatMessages.map(r=>`<article class="message user-message"><div class="message-author"><strong>Vos</strong></div><div class="message-body">${escape(r.source.message)}</div></article>${r.steps.map(step=>`<article class="message"><div class="message-author"><strong>${escape(step.agent)}</strong><span class="tiny">→ ${escape(step.target||'equipo')}${step.kind==='delegation'?' · consulta':''}</span></div><div class="message-body">${escape(step.output)}</div></article>`).join('')}${r.partial?.output?`<article class="message"><div class="message-author"><strong>${escape(r.partial.agent)}</strong></div><div class="message-body">${escape(r.partial.output)}</div></article>`:''}${['queued','running'].includes(r.status)?`<p class="pending">${escape(r.currentAgent||main.name)} está trabajando… <button class="quiet" data-teamchat-cancel="${r.id}">Detener</button></p>`:''}${r.error?`<p class="error">${escape(r.error)} ${['failed','interrupted','cancelled'].includes(r.status)?`<button class="quiet" data-teamchat-resume="${r.id}">Continuar</button>`:''}</p>`:''}`).join('')||'<p class="muted">Escribí al equipo. El coordinador consultará a sus integrantes cuando lo necesite.</p>'}</div><form id="team-chat-form" class="chat-compose"><label class="sr-only" for="team-chat-recipient">Destinatario</label><select id="team-chat-recipient" name="recipient" aria-label="Destinatario">${team.agents.map((a,i)=>`<option value="${i}" ${i===teamChatRecipient?'selected':''}>${escape(a.name)}</option>`).join('')}</select><label class="sr-only" for="team-chat-input">Mensaje al equipo</label><textarea id="team-chat-input" name="message" maxlength="4000" required placeholder="Escribile al equipo…" ${busy?'disabled':''}></textarea><button class="primary" ${busy?'disabled':''}>Enviar</button></form></div>`;
    if(activeRun&&(activeRun.source?.participants||[]).some(p=>p.agent.browser))loadBrowser(activeRun.id);
  }
  if (view === 'teams') {
    $('#content').innerHTML = heading('El trabajo, compartido.','Formá un equipo. Dale un objetivo. Seguí sus resultados.', '<button class="primary" data-action="new">＋ Crear equipo</button>') +
      `<div class="banner"><span class="spark">✳</span><div><h2>Tus agentes. Tus cuentas.</h2><p>Conectá los programas oficiales de Codex, Claude Code o Kimi Code. Cada agente puede usar uno distinto. El equipo avanza por etapas y conserva los resultados en tu computadora.</p></div></div>` +
      (state.teams.length ? `<div class="grid">${state.teams.map(t => `<article class="card"><div class="card-top">${teamAvatar(t.id)}<span class="badge">${t.agents.length} AGENTES</span></div><h3>${escape(t.name)}</h3><p class="tiny">Flujo secuencial · resultados compartidos</p>${t.agents.map((a,i) => `<div class="agent-line">${agentAvatar(a)}<div><p>${escape(a.name)}</p><small>${escape(providerName(a.provider))}</small></div><button class="quiet" data-chat-team="${t.id}" data-chat-agent="${i}">Chat</button>${t.id!==state.mainTeamId?`<button class="quiet" data-delete-agent="${t.id}" data-agent-index="${i}">Eliminar</button>`:''}</div>`).join('')}<button class="quiet" data-browser-access="${t.id}">Sitios permitidos · ${t.browserAccess?.mode==='internal'?'Chromium interno':t.browserAccess?.mode==='existing'?'Mis sesiones':'Sesión independiente'}</button><div class="card-footer"><span>Listo para un objetivo</span><button class="quiet" data-team-edit="${t.id}">Editar</button>${t.id!==state.mainTeamId?`<button class="quiet" data-team-delete="${t.id}">Borrar</button>`:''}<button class="secondary" data-task="${t.id}">Asignar trabajo ↗</button></div></article>`).join('')}</div>` :
      `<div class="empty"><h2>Tu primer equipo empieza acá</h2><p>Probá un equipo de análisis y revisión.<br>La demostración permite explorar sin consumir tu suscripción.</p><button class="secondary" data-action="demo">Crear equipo de demostración</button></div>`);
  }
  if(view==='connectors'){renderConnectors();}
  if(view==='whatsapp'){renderWhatsApp();}
  if(view==='phones'){renderPhones();}
  if(view==='updates'){renderUpdates();}
  if (view === 'providers') $('#content').innerHTML = heading('Conectá tus cuentas.','La autenticación queda en las herramientas oficiales de cada proveedor.') +
    `<div class="banner"><div><h2>Estado de tus cuentas</h2><p>Se muestran las cuentas vinculadas y los servidores locales con modelos disponibles. Para agregar una cuenta, iniciá sesión en su programa y volvé a abrir Conexiones. Las cuotas se muestran cuando el proveedor las informa.</p></div></div><div class="grid">${connectedProviders().map(p=>`<article class="card"><span class="badge">${escape(p.accountLabel||(p.installed?'DISPONIBLE':'NO DETECTADO'))}</span><h3>${escape(p.name)}</h3><p class="provider-note">${escape(p.detail)}</p>${p.id==='kimi'&&p.accountState==='connected'?'<button class="secondary" data-use-kimi>Crear agente con Kimi</button>':p.login&&p.accountState!=='connected'?`<code>${escape(p.login)}</code>`:''}<p class="tiny">${escape(p.version)}</p><div data-usage-card="${p.id}">${usageHtml(p.id)}</div></article>`).join('')||'<p class="tiny">No hay cuentas conectadas. Iniciá sesión en un proveedor compatible y volvé a abrir Conexiones.</p>'}</div><p class="provider-note">Ollama y LM Studio usan modelos disponibles en sus servidores locales y, por ahora, no disponen de las herramientas de navegador ni de archivos de Tropa. Las cuentas de los demás programas no se conectan automáticamente por tener un ícono.</p>`;
  if(view==='providers'){ $('#content').insertAdjacentHTML('beforeend', browserConnectionHtml()); loadBrowserConnection(); }
  if(view==='internal'){renderInternalBrowser();}
  if (view === 'runs') {
    const r = state.runs.find(r=>r.id===selectedRun && r.source?.kind!=='chat') || state.runs.find(r=>r.source?.kind!=='chat');
    if (r) {
      selectedRun=r.id;
      $('#content').innerHTML=`<div class="workspace"><div class="conversation"><div class="conversation-head"><div><h2>${escape(r.team.name)}</h2><span class="tiny">${new Date(r.createdAt).toLocaleString('es-AR',{timeZone:'America/Argentina/Buenos_Aires'})} · Conversación del equipo</span></div><button class="secondary" ${r.source?`data-op-run="${r.source.kind}/${r.source.id}"`:`data-task="${r.team.id}"`}>${r.source?'↻ Repetir ejecución':'＋ Nuevo objetivo'}</button></div>${r.team.agents.some(a=>a.browser)?`<section class="browser-panel" id="run-browser" data-browser-run="${r.id}"><p class="tiny">Cargando navegador…</p></section>`:''}<div class="messages"><article class="message user-message"><div class="message-author"><span class="avatar">T</span><strong>Vos</strong></div><div class="message-body">${escape(r.objective)}</div></article>${r.steps.map(s=>`<article class="message"><div class="message-author">${agentAvatar(r.team.agents.find(a=>a.name===s.agent)||{name:s.agent})}<strong>${escape(s.agent)}</strong>${s.node!==undefined?`<span class="badge step-badge">Paso ${s.node+1}</span>`:''}<span class="tiny">${escape(providerName(s.provider))}</span></div><div class="message-body">${escape(s.output)}</div></article>`).join('')}${r.status==='running'?`<article class="message pending">${animatedAgent(r.team.agents.find(a=>a.name===r.currentAgent),r.status)} ${escape(r.currentAgent)} está trabajando…</article>`:''}${r.status==='waiting'&&r.waiting?`<article class="message flow-approval"><h3>✋ El flujo espera tu aprobación · Paso ${r.waiting.node+1}</h3><p>${escape(r.waiting.message)}</p><button class="primary" data-flow-approve="${r.id}" data-allow="true">Aprobar y continuar</button> <button class="secondary" data-flow-approve="${r.id}" data-allow="false">Detener el flujo</button></article>`:''}${r.error?`<p class="error">${escape(r.error)}</p>`:''}</div><div class="conversation-footer"><span>${r.status==='completed'?'✓ Objetivo completado':escape(labels[r.status])}</span><button class="quiet" ${r.source?`data-op-run="${r.source.kind}/${r.source.id}"`:`data-task="${r.team.id}"`}>${r.source?'Repetir ejecución ↗':'Asignar otro objetivo ↗'}</button></div></div><section class="inspector"><div class="inspector-title">EN ESTA CONVERSACIÓN</div><div class="status ${r.status}">${escape(labels[r.status])}</div><p class="tiny">${runLabel(r)}</p>${r.source?.mode==='flow'?`<div class="inspector-title">PASOS</div>${r.source.nodes.map((n,i)=>`<div class="agent-line"><span class="avatar">${i+1}</span><div><p>${escape(n.title)}</p><small>${r.source.outputs[i]!==undefined||r.steps.some(s=>s.node===i&&['condition','approval'].includes(s.kind))?'✓ Finalizó':i===r.source.cursor&&r.status==='running'?'En curso':i===r.source.cursor&&r.status==='waiting'?'Esperando aprobación':r.source.stoppedAt!==undefined&&i>r.source.stoppedAt||i<r.source.cursor?'Omitido':'Pendiente'}</small></div></div>`).join('')}`:`<div class="inspector-title">EQUIPO</div>${r.team.agents.map((a,i)=>`<div class="agent-line">${agentAvatar(a)}<div><p>${escape(a.name)}</p><small>${i<r.steps.length?'✓ Finalizó':i===r.steps.length&&r.status==='running'?'En curso':'Pendiente'}</small></div></div>`).join('')}`}<div class="inspector-title">ARCHIVOS</div><button class="secondary" data-files="${r.id}">Ver archivos generados</button><div id="run-files"></div><div class="inspector-title">DETALLES</div><p class="provider-note">${r.team.agents.some(a=>a.provider==='demo')?'Demostración con respuestas simuladas.':'Este equipo utiliza tus programas oficiales de IA.'}</p><p class="provider-note">Resultados guardados en esta computadora.</p>${['running','queued'].includes(r.status)?`<button class="secondary" data-cancel="${r.id}">Detener ejecución</button>`:['failed','interrupted','cancelled'].includes(r.status)?`<button class="secondary" data-resume="${r.id}">Continuar pendiente</button>`:''}</section></div>`;
      if(r.team.agents.some(a=>a.browser))loadBrowser(r.id);
    } else $('#content').innerHTML=`<div class="welcome"><span class="welcome-symbol">◈</span><h1>¿Qué hacemos hoy?</h1><p class="muted">Un espacio para vos y tus agentes.<br>Creá un equipo para empezar una conversación.</p><button class="primary" data-action="new">＋ Crear mi primer equipo</button><button class="quiet" data-action="demo">Explorar con una demostración</button></div>`;
  }
  if (view === 'task') {
    const t = state.teams.find(t=>t.id===selectedTeam);
    $('#content').innerHTML = heading('Un objetivo para tu equipo.',escape(t.name)) + `<form id="task-form" class="card task-form"><label>¿Qué querés conseguir?<textarea name="objective" maxlength="12000" placeholder="Incluí el objetivo, los datos disponibles y cómo debería ser el resultado." required></textarea></label><p class="provider-note">${t.agents.map(a=>escape(a.name)).join(' → ')}. Cada etapa recibe las anteriores. Los agentes con herramientas pueden buscar en la web y crear entregables en una carpeta compartida de esta ejecución.</p><p class="provider-note">${t.agents.every(a=>a.provider==='demo')?'Este equipo es una simulación, sin llamadas a IA.':'Al iniciar se ejecutan los programas oficiales y se consume la cuota de tus cuentas. Las herramientas dependen de lo habilitado para cada agente. Los archivos adjuntos y el objetivo se comparten con los proveedores elegidos.'}</p>${t.agents.some(a=>a.browser)?`<div class="browser-hint"><strong>Navegador visual habilitado</strong><p>Capturas y solicitudes de autorización aparecerán en la conversación. ${['existing','internal'].includes(t.browserAccess?.mode)?'Se usará tu sesión en los sitios: '+escape(t.browserAccess.sites.join(', '))+'. El contenido y las capturas se comparten con las IA del equipo.':'Se usa una sesión independiente, sin las cookies de tu navegador personal.'}</p><button type="button" class="secondary" data-browser-access="${t.id}">Elegir sitios y sesiones</button><p></p>${['existing','internal'].includes(t.browserAccess?.mode)?'<button type="button" class="secondary" data-personal-demo>Preparar prueba de lectura de sesión</button>':'<button type="button" class="secondary" data-browser-demo>Preparar prueba de formulario local</button>'}</div>`:''}<label>Archivos de entrada (TXT, MD, CSV o JSON; máximo 5 y 50 KB)<input type="file" name="files" accept=".txt,.md,.csv,.json" multiple></label><div class="form-footer"><button type="button" class="quiet" data-view="teams">Volver</button><button class="primary">Iniciar trabajo</button></div></form>`;
  }
}
function addAgent(defaults={}) {
  if ($('#agent-fields').children.length >= 8) return notice('Máximo: 8 agentes.');
  const box=document.createElement('div');box.className='agent-fields';
  box.innerHTML=`${agentAvatarChoice()}<div class="row"><label>Nombre<input name="agent-name" maxlength="80" required value="${escape(defaults.name||'')}" placeholder="Analista"></label><label>Cuenta / proveedor<select name="provider" required>${providerOptions(defaults.provider)}</select></label></div><label>Función del agente<textarea name="instructions" maxlength="2000" required placeholder="Qué debe hacer y qué resultado debe entregar">${escape(defaults.instructions||'')}</textarea></label><label>Modelo (opcional)<input name="model" maxlength="100" placeholder="Vacío: modelo configurado en el proveedor"></label><label class="tools-choice"><input type="checkbox" name="tools"> Habilitar búsqueda web y archivos (GPT / Claude)</label><label class="tools-choice"><input type="checkbox" name="browser"> Navegador visual (GPT / Claude)</label><button type="button" class="quiet" data-remove>Quitar agente</button>`;
  $('#agent-fields').append(box);
  if(defaults.model)box.querySelector('[name="model"]').value=defaults.model;
  box.querySelector('[name="tools"]').checked=!!defaults.tools;box.querySelector('[name="browser"]').checked=!!defaults.browser;
  if(defaults.avatar){const sel=box.querySelector('[name="avatar"]');sel.value=defaults.avatar;sel.closest('.agent-avatar-choice').querySelector('.agent-avatar-preview').innerHTML=agentAvatar({avatar:defaults.avatar});}
  syncLocalProvider(box.querySelector('[name=provider]'));
  if(defaults.from!==undefined)box.dataset.from=defaults.from;
  if(defaults.locked)box.querySelector('[data-remove]').remove(); fieldCount++;
}
document.addEventListener('click', async e=> {
  const b=e.target.closest('button'); if(!b)return;
  try {
    if(b.hasAttribute('data-personal-demo')){const t=state.teams.find(t=>t.id===selectedTeam);$('#task-form [name="objective"]').value=`Usá browser_open para abrir ${t.browserAccess.sites[0]} en el navegador autorizado del equipo. Esperá mi autorización, inspeccioná la página y resumí lo que ves. No pulses enlaces, no completes formularios y no modifiques información. Si hay más agentes, deben verificar la misma página con browser_inspect.`;}
    if(b.hasAttribute('data-browser-demo'))$('#task-form [name="objective"]').value=`Usá el navegador visual para abrir ${location.origin}/browser-demo . Inspeccioná la página, completá Nombre de prueba con Equipo Comunidad, elegí Soporte y escribí Verificación de navegación visual en Descripción. Hacé clic en Enviar prueba local. Comprobá el código de confirmación y entregá un resumen de lo que realmente hiciste. Si hay un segundo agente, debe revisar el resultado en el mismo navegador sin reenviar el formulario. No uses búsqueda web ni comandos de terminal para reemplazar las herramientas browser_*. Sólo el primer agente completa el formulario; los siguientes verifican.`;
    if(b.dataset.symbol){$('.bot-face').textContent=b.dataset.symbol;}
    if(b.dataset.color){document.querySelectorAll('[data-color]').forEach(x=>{x.classList.toggle('chosen',x===b);x.setAttribute('aria-pressed',x===b);});$('.avatar-preview').className='avatar-preview '+b.dataset.color;}
    if(b.dataset.shape){document.querySelectorAll('[data-shape]').forEach(x=>{x.classList.toggle('chosen',x===b);x.setAttribute('aria-pressed',x===b);});$('.bot-face').className='bot-face '+b.dataset.shape;}
    if(b.dataset.preset){const p=agentPresets[b.dataset.preset];if(!p)throw Error('Perfil no encontrado.');const f=$('#create-agent-form');f.elements.name.value=p.name;f.elements.instructions.value=p.instructions;f.elements.avatar.value=p.avatar;$('#avatar-collection').value='personajes';$('.avatar-art-preview').innerHTML=agentAvatar({avatar:p.avatar});$('.art-grid').innerHTML=avatarGrid('personajes',p.avatar);document.querySelectorAll('[data-preset]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));f.elements.name.focus();}
    if(b.dataset.teamChat){selectedTeam=b.dataset.teamChat;teamChatRecipient=0;teamChatMessages=await api(`teams/${selectedTeam}/chat`);view='teamchat';render();}
    if(b.dataset.teamchatCancel){await api(`runs/${b.dataset.teamchatCancel}/cancel`,{});teamChatMessages=await api(`teams/${selectedTeam}/chat`);render();}
    if(b.dataset.teamchatResume){await api(`runs/${b.dataset.teamchatResume}/resume`,{});teamChatMessages=await api(`teams/${selectedTeam}/chat`);render();}
    if(b.dataset.cancelChat){await api(`runs/${b.dataset.cancelChat}/cancel`,{});chatMessages=await api(`teams/${selectedTeam}/agents/${selectedAgent}/chat`);render();}
    if(b.dataset.resumeChat){await api(`runs/${b.dataset.resumeChat}/resume`,{});chatMessages=await api(`teams/${selectedTeam}/agents/${selectedAgent}/chat`);render();}
    if(b.dataset.chatTeam){selectedTeam=b.dataset.chatTeam;selectedAgent=Number(b.dataset.chatAgent);chatMessages=await api(`teams/${selectedTeam}/agents/${selectedAgent}/chat`);view='chat';render();}
    if(b.hasAttribute('data-use-kimi')){view='create';render();$('#agent-provider').value='kimi';notice('Kimi seleccionado para el nuevo agente.');}
    if(b.dataset.view){captureFlow();view=b.dataset.view;if(view==='runs' && state.teams.length){selectedTeam=state.teams[0].id;selectedAgent=0;chatMessages=await api(`teams/${selectedTeam}/agents/0/chat`);view='chat';}notice();state=await api('state');if(view==='providers'){connections=await api('providers');loadUsage();}render();}
    if(b.dataset.action==='new'){ delete $('#team-form').dataset.editing;$('#team-form h2').textContent='Creá tu equipo';$('#add-agent').hidden=false;$('#team-form').reset();$('#agent-fields').replaceChildren();addAgent();$('#team-dialog').showModal(); }
    if(b.dataset.action==='demo') {await api('teams',{name:'Mesa de análisis · demo',agents:[{name:'Analista',provider:'demo',instructions:'Organizá la información y señalá lo que falta.'},{name:'Revisor',provider:'demo',instructions:'Revisá el análisis y prepará un resumen con próximos pasos.'}]});await refresh();}
    if(b.dataset.browserDecision){await api(`runs/${b.dataset.run}/browser/decide`,{id:b.dataset.browserDecision,allow:b.dataset.allow==='true'});await loadBrowser(b.dataset.run);}
    if(b.dataset.browserClose){await api(`runs/${b.dataset.browserClose}/browser/close`,{});await loadBrowser(b.dataset.browserClose);}
    if(b.dataset.files){const files=await api(`runs/${b.dataset.files}/files`);$('#run-files').innerHTML=files.map(f=>`<div class="artifact-item"><span>${escape(f.name)} · ${Math.ceil(f.size/1024)} KB</span><button data-preview="${escape(f.name)}" data-run="${b.dataset.files}">Abrir</button><a href="/api/runs/${b.dataset.files}/files?name=${encodeURIComponent(f.name)}" download>Descargar</a></div>`).join('')||'<p class="tiny">Todavía no hay archivos.</p>';}
    if(b.dataset.preview){const r=await fetch(`/api/runs/${b.dataset.run}/files?name=${encodeURIComponent(b.dataset.preview)}`);if(!r.ok)throw Error('No se pudo abrir el archivo.');$('#file-preview-name').textContent=b.dataset.preview;$('#file-preview-text').textContent=await r.text();$('#file-preview').showModal();}
    if(b.dataset.open){selectedRun=b.dataset.open;view='runs';notice();render();}
    if(b.dataset.task){selectedTeam=b.dataset.task;view='task';render();}
    if(b.hasAttribute('data-remove'))b.closest('.agent-fields').remove();
    if(b.dataset.cancel){await api(`runs/${b.dataset.cancel}/cancel`,{});await refresh();}
    if(b.dataset.resume && confirm('Se repetirá únicamente la etapa pendiente, que puede consumir cuota. ¿Continuar?')){await api(`runs/${b.dataset.resume}/resume`,{});await refresh();}
  } catch(e){notice(e.message);}
});
$('#add-agent').onclick=()=>addAgent();$('#close-dialog').onclick=()=>$('#team-dialog').close();
document.addEventListener('click',async e=>{
 const b=e.target.closest('button');if(!b)return;
 try{
  if(b.dataset.teamEdit){
   const t=state.teams.find(x=>x.id===b.dataset.teamEdit);if(!t)return;
   const f=$('#team-form'),main=t.id===state.mainTeamId;f.reset();f.dataset.editing=t.id;$('#agent-fields').replaceChildren();
   f.querySelector('h2').textContent=main?'Editar agente principal':'Editar equipo';f.elements.name.value=t.name;
   t.agents.forEach((a,i)=>addAgent({...a,from:i,locked:main}));$('#add-agent').hidden=main;$('#team-dialog').showModal();
  }
  if(b.dataset.deleteAgent){
   const t=state.teams.find(x=>x.id===b.dataset.deleteAgent),index=Number(b.dataset.agentIndex),agent=t?.agents[index];
   if(!agent||t.id===state.mainTeamId)return;
   const last=t.agents.length===1;
   if(!confirm(last?`¿Eliminar a «${agent.name}»? También se eliminará el equipo «${t.name}», porque quedaría vacío. Las conversaciones se conservan en el historial.`:`¿Eliminar a «${agent.name}» del equipo «${t.name}»? Su conversación se conserva en el historial.`))return;
   if(last)await api(`teams/${t.id}/delete`,{});
   else await api(`teams/${t.id}/update`,{name:t.name,agents:t.agents.map((a,i)=>({...a,from:i})).filter((_,i)=>i!==index)});
   if(selectedTeam===t.id){if(last||selectedAgent===index){view='teams';selectedTeam=null;chatMessages=[];}else if(selectedAgent>index)selectedAgent--;}
   await refresh();notice('Agente eliminado.');
  }
  if(b.dataset.teamDelete){
   const t=state.teams.find(x=>x.id===b.dataset.teamDelete);
   if(t&&confirm(`¿Borrar el equipo «${t.name}»? Sus conversaciones quedan en el historial.`)){await api(`teams/${t.id}/delete`,{});await refresh();notice('Equipo borrado.');}
  }
 }catch(err){notice(err.message);}
});
$('#team-form').onsubmit=async e=>{e.preventDefault();const submit=e.submitter;submit.disabled=true;try{const agents=[...document.querySelectorAll('.agent-fields')].map(box=>({name:box.querySelector('[name="agent-name"]').value,provider:box.querySelector('[name="provider"]').value,instructions:box.querySelector('[name="instructions"]').value,model:box.querySelector('[name="model"]').value,tools:box.querySelector('[name="tools"]').checked,browser:box.querySelector('[name="browser"]').checked,avatar:box.querySelector('[name="avatar"]').value,from:box.dataset.from===undefined?null:Number(box.dataset.from)}));const editing=$('#team-form').dataset.editing,name=$('#team-form [name="name"]').value;if(editing)await api(`teams/${editing}/update`,{name,agents});else await api('teams',{name,agents:agents.map(({from,...a})=>a)});delete $('#team-form').dataset.editing;$('#team-dialog').close();notice();await refresh();}catch(e){notice(e.message);}finally{submit.disabled=false;}};
document.addEventListener('submit',async e=>{if(e.target.id!=='task-form')return;e.preventDefault();const b=e.submitter;b.disabled=true;try{const attachments=[...e.target.elements.files.files];if(attachments.length>5||attachments.reduce((sum,f)=>sum+f.size,0)>50000)throw Error('Máximo: 5 archivos y 50 KB en total.');const run=await api('runs',{teamId:selectedTeam,objective:e.target.elements.objective.value,files:await Promise.all([...e.target.elements.files.files].map(async file=>({name:file.name,content:await file.text()})))});selectedRun=run.id;view='runs';notice();await refresh();}catch(e){notice(e.message);b.disabled=false;}});
