let flowDraft = null;
const teamOptions = selected => state.teams.map(t=>`<option value="${t.id}" ${t.id===selected?'selected':''}>${escape(t.name)}</option>`).join('');
const agentOptions = (teamId,index) => state.teams.map(t=>t.agents.map((a,i)=>`<option value="${t.id}:${i}" ${t.id===teamId&&i===Number(index)?'selected':''}>${escape(a.name)} · ${escape(t.name)}</option>`).join('')).join('');
const memberOptions = (teamId,index) => (state.teams.find(t=>t.id===teamId)?.agents||[]).map((a,i)=>`<option value="${i}" ${i===Number(index)?'selected':''}>${escape(a.name)}</option>`).join('');
const nodeKinds = {agent:['✳ AGENTE','Un agente hace una tarea'],team:['◎ EQUIPO','El coordinador puede consultar al resto del equipo'],condition:['◇ CONDICIÓN','Decide si el flujo sigue'],approval:['✋ APROBACIÓN','Pausa hasta que lo apruebes']};
const runLabel = r => r.source?.mode==='flow'?`Paso ${Math.min(r.source.cursor+1,r.source.nodes.length)} de ${r.source.nodes.length}`:`${r.steps.length}/${r.team.agents.length} etapas`;
function newNode(type) {
 const t=state.teams[0];
 if(type==='approval')return {type,message:''};
 if(type==='condition')return {type,mode:'contains',value:'',onFalse:'stop',teamId:t.id,index:0};
 return {type,teamId:t.id,index:0,instruction:'',input:'all'};
}
function inputSelect(n,i) {
 return `<label>Recibe<select data-n="${i}" data-f="input"><option value="all" ${n.input==='all'?'selected':''}>Todos los pasos anteriores</option><option value="last" ${n.input==='last'?'selected':''}>Solo el paso anterior</option><option value="none" ${n.input==='none'?'selected':''}>Solo el objetivo</option></select></label>`;
}
function flowNode(n,i,total) {
 const [kind,hint]=nodeKinds[n.type];let body='';
 if(n.type==='agent')body=`<label>Agente<select data-n="${i}" data-f="agent">${agentOptions(n.teamId,n.index)}</select></label><label>Tarea de este paso<textarea data-n="${i}" data-f="instruction" maxlength="4000" placeholder="Qué tiene que hacer y entregar">${escape(n.instruction||'')}</textarea></label>${inputSelect(n,i)}`;
 if(n.type==='team')body=`<label>Equipo<select data-n="${i}" data-f="team" data-rerender>${teamOptions(n.teamId)}</select></label><label>Coordina<select data-n="${i}" data-f="index">${memberOptions(n.teamId,n.index)}</select></label><label>Tarea del equipo<textarea data-n="${i}" data-f="instruction" maxlength="4000" placeholder="Qué tiene que resolver el equipo">${escape(n.instruction||'')}</textarea></label>${inputSelect(n,i)}`;
 if(n.type==='condition')body=`<label>Se evalúa<select data-n="${i}" data-f="mode" data-rerender><option value="contains" ${n.mode==='contains'?'selected':''}>El resultado anterior contiene…</option><option value="not_contains" ${n.mode==='not_contains'?'selected':''}>El resultado anterior no contiene…</option><option value="agent" ${n.mode==='agent'?'selected':''}>Lo decide un agente</option></select></label><label>${n.mode==='agent'?'Pregunta (sí / no)':'Texto'}<input data-n="${i}" data-f="value" maxlength="2000" value="${escape(n.value||'')}" placeholder="${n.mode==='agent'?'¿El borrador incluye precios?':'APROBADO'}"></label>${n.mode==='agent'?`<label>Agente que decide<select data-n="${i}" data-f="agent">${agentOptions(n.teamId,n.index)}</select></label>`:''}<label>Si no se cumple<select data-n="${i}" data-f="onFalse" data-rerender><option value="stop" ${n.onFalse!=='goto'?'selected':''}>Terminar el flujo</option>${i<total-1?`<option value="goto" ${n.onFalse==='goto'?'selected':''}>Saltar a otro paso</option>`:''}</select></label>${n.onFalse==='goto'?`<label>Saltar al<select data-n="${i}" data-f="target">${Array.from({length:total-i-1},(_,k)=>i+k+1).map(k=>`<option value="${k}" ${Number(n.target)===k?'selected':''}>Paso ${k+1}</option>`).join('')}</select></label>`:''}`;
 if(n.type==='approval')body=`<label>Qué revisar<textarea data-n="${i}" data-f="message" maxlength="2000" placeholder="Revisá el borrador antes de enviarlo">${escape(n.message||'')}</textarea></label><p>El flujo queda en pausa hasta que lo apruebes en Conversaciones.</p>`;
 return `<span class="flow-arrow">↓</span><article class="flow-node flow-step ${n.type}"><span class="node-kind">${kind} · PASO ${i+1}</span><p class="tiny">${hint}</p>${body}<div class="node-actions"><button type="button" data-move="${i}" ${i===0?'disabled':''}>← Antes</button><button type="button" data-move-down="${i}" ${i===total-1?'disabled':''}>Después →</button><button type="button" data-drop="${i}">Quitar</button></div></article>`;
}
function renderOperations() {
 if(!['routines','workflows','tasks','schedules'].includes(view))return false;
 const list=state[view]||[];
 if(view==='tasks') {
  $('#content').innerHTML=heading('Tareas','Seguí el trabajo de tus agentes y abrí sus resultados.')+`<div class="task-board">${[['En curso',['running','queued']],['Finalizadas',['completed']],['Necesitan atención',['waiting','failed','cancelled','interrupted']]].map(([name,statuses])=>`<section><h2>${name}</h2>${state.runs.filter(r=>statuses.includes(r.status)).map(r=>`<button class="task-tile" data-open="${r.id}"><span class="badge">${labels[r.status]}</span><h3>${escape(r.team.name)}</h3><p>${escape(r.objective.slice(0,160))}</p><small>${runLabel(r)}</small></button>`).join('')||'<p class="tiny">Sin tareas</p>'}</section>`).join('')}</div>`;return true;
 }
 if(view==='workflows'&&flowDraft) {
  const d=flowDraft;
  $('#content').innerHTML=`<form id="workflow-form"><div class="flow-heading"><input aria-label="Nombre del flujo" name="name" maxlength="80" required value="${escape(d.name)}"><button type="button" data-flow-back>Volver</button><button class="primary">Guardar flujo</button></div><div class="flow-canvas"><div class="flow-chain"><article class="flow-node trigger"><span class="node-kind">⚡ ACTIVADOR</span><h3>Manual o programado</h3><p>Ejecutalo cuando quieras o programalo en Programación.</p></article><span class="flow-arrow">↓</span><article class="flow-node"><span class="node-kind">▤ OBJETIVO</span><textarea name="objective" aria-label="Objetivo del flujo" required maxlength="12000" placeholder="¿Qué debe conseguir este flujo?">${escape(d.objective)}</textarea></article>${d.nodes.map((n,i)=>flowNode(n,i,d.nodes.length)).join('')}<span class="flow-arrow">↓</span><div class="add-node-menu"><span class="node-kind">＋ AÑADIR PASO</span>${Object.entries(nodeKinds).map(([type,[kind]])=>`<button type="button" class="add-node" data-add-node="${type}">${kind}</button>`).join('')}</div><span class="flow-arrow">↓</span><article class="flow-node output"><span class="node-kind">↗ SALIDA</span><h3>Resultado guardado</h3><p>Disponible en Tareas. Los archivos quedan en la carpeta de la ejecución.</p></article></div><div class="canvas-note">Los pasos se ejecutan en orden · Cada agente usa los permisos de su equipo · Una condición puede terminar el flujo o saltar a un paso posterior</div></div></form>`;return true;
 }
 const info={routines:['Rutinas','Objetivos reutilizables para tus equipos.','Nueva rutina'],workflows:['Flujos de trabajo','Automatizá tareas con agentes, equipos, condiciones y aprobaciones.','Nuevo flujo'],schedules:['Programación','Ejecutá rutinas y flujos automáticamente mientras el motor local esté encendido.','Nueva programación']}[view];
 const target=x=>{const item=(state[x.targetKind||'routines']||[]).find(r=>r.id===(x.targetId||x.routineId));return item?`${x.targetKind==='workflows'?'Flujo':'Rutina'}: ${escape(item.name)}`:'Elemento borrado';};
 $('#content').innerHTML=heading(info[0],info[1],`<button class="primary" data-op-new="${view}">＋ ${info[2]}</button>`)+(view==='schedules'?'<p class="operations-note">Las fechas se muestran en hora de Buenos Aires. Si el motor estuvo apagado, se ejecutará una sola vez al volver, sin acumular repeticiones.</p>':'')+`<div class="grid">${list.map(x=>`<article class="card"><span class="badge">${view==='schedules'?(x.enabled?'ACTIVA':'PAUSADA / FINALIZADA'):view==='workflows'?`${x.nodes.length} PASOS`:'REUTILIZABLE'}</span><h3>${escape(x.name)}</h3><p class="provider-note">${view==='schedules'?`${target(x)}<br>${new Date(x.nextAt).toLocaleString('es-AR',{timeZone:'America/Argentina/Buenos_Aires'})} · ${x.intervalMinutes?`Cada ${x.intervalMinutes} min`:'Una vez'}`:escape(x.objective.slice(0,180))}</p>${x.error?`<p class="error">${escape(x.error)}</p>`:''}<div class="card-footer">${view==='schedules'?`<button data-op-toggle="${x.id}">${x.enabled?'Pausar':'Activar'}</button>${x.lastRunId?`<button data-open="${x.lastRunId}">Ver tarea</button>`:''}<button class="quiet" data-op-delete="${view}/${x.id}">Borrar</button>`:`<button data-op-edit="${view}/${x.id}">Editar</button><button class="quiet" data-op-duplicate="${view}/${x.id}">Duplicar</button><button class="quiet" data-op-delete="${view}/${x.id}">Borrar</button><button class="primary" data-op-run="${view}/${x.id}">Ejecutar</button>`}</div></article>`).join('')||'<div class="empty"><h2>Todo empieza con un objetivo</h2><p class="muted">Creá el primero con el botón de arriba.</p></div>'}</div><div id="operation-editor"></div>`;
 return true;
}
function captureFlow() {
 if(!$('#workflow-form'))return;
 flowDraft.name=$('#workflow-form [name="name"]').value;flowDraft.objective=$('#workflow-form [name="objective"]').value;
 document.querySelectorAll('#workflow-form [data-n]').forEach(el=>{
  const n=flowDraft.nodes[Number(el.dataset.n)],f=el.dataset.f;if(!n)return;
  if(f==='agent'){const [teamId,index]=el.value.split(':');n.teamId=teamId;n.index=Number(index);}
  else if(f==='team'){if(n.teamId!==el.value){n.teamId=el.value;n.index=0;}}
  else if(f==='index'||f==='target')n[f]=Number(el.value);
  else n[f]=el.value;
 });
}
function operationEditor(kind,item={}) {
 if(kind==='workflows'){if(!state.teams.length)return notice('Creá un agente o equipo antes de armar un flujo.');const copy=structuredClone(item);delete copy.legacy;flowDraft={name:'Flujo de trabajo sin título',objective:'',nodes:[],...copy};render();return;}
 if(!state.teams.length)return notice('Creá un agente o equipo antes de una rutina.');
 if(kind==='schedules'&&!state.routines.length&&!state.workflows.length)return notice('Guardá una rutina o un flujo antes de programarlo.');
 const targets=[...state.routines.map(r=>`<option value="routines:${r.id}">Rutina · ${escape(r.name)}</option>`),...state.workflows.map(w=>`<option value="workflows:${w.id}">Flujo · ${escape(w.name)}</option>`)].join('');
 $('#operation-editor').innerHTML=`<form id="operation-form" class="card task-form" data-kind="${kind}" data-id="${item.id||''}"><h2>${kind==='routines'?'Configurar rutina':'Programar una rutina o un flujo'}</h2><label>Nombre<input name="name" required maxlength="80" value="${escape(item.name||'')}"></label>${kind==='routines'?`<label>Equipo<select name="teamId">${teamOptions(item.teamIds?.[0])}</select></label><label>Objetivo<textarea name="objective" required maxlength="12000">${escape(item.objective||'')}</textarea></label>`:`<label>Qué ejecutar<select name="target">${targets}</select></label><label>Primera ejecución (hora de este dispositivo)<input type="datetime-local" name="date" required></label><label>Repetición<select name="intervalMinutes"><option value="0">Una sola vez</option><option value="60">Cada hora</option><option value="1440">Cada 24 horas</option><option value="10080">Cada 7 días</option></select></label><p class="provider-note">Al guardar se activa la programación. Las ejecuciones usan la cuota de las cuentas elegidas en cada equipo. Si un flujo tiene un paso de aprobación, la ejecución espera hasta que respondas.</p>`}<button class="primary">Guardar</button></form>`;
 $('#operation-editor').scrollIntoView({behavior:'smooth'});
}
document.addEventListener('change',e=>{
 if(!e.target.closest('#workflow-form')||!e.target.hasAttribute('data-rerender'))return;
 captureFlow();render();
});
document.addEventListener('click',async e=>{
 const b=e.target.closest('button');if(!b)return;
 try {
  if(b.dataset.opNew)operationEditor(b.dataset.opNew);
  if(b.dataset.opEdit){const [kind,id]=b.dataset.opEdit.split('/');operationEditor(kind,state[kind].find(x=>x.id===id));}
  if(b.hasAttribute('data-flow-back')){flowDraft=null;render();}
  if(b.dataset.addNode){captureFlow();if(!state.teams.length)return notice('Creá un equipo primero.');if(flowDraft.nodes.length>=20)return notice('Máximo: 20 pasos.');flowDraft.nodes.push(newNode(b.dataset.addNode));render();}
  if(b.dataset.drop!==undefined){captureFlow();const i=Number(b.dataset.drop);flowDraft.nodes.splice(i,1);flowDraft.nodes.forEach((n,k)=>{if(n.onFalse==='goto'&&(n.target>=flowDraft.nodes.length||n.target<=k)){n.onFalse='stop';delete n.target;}else if(n.onFalse==='goto'&&n.target>i)n.target--;});render();}
  if(b.dataset.move!==undefined||b.dataset.moveDown!==undefined){captureFlow();const i=b.dataset.move!==undefined?Number(b.dataset.move):Number(b.dataset.moveDown)+1,list=flowDraft.nodes;if(i>0&&i<list.length){[list[i-1],list[i]]=[list[i],list[i-1]];list.forEach((n,k)=>{if(n.onFalse==='goto'&&n.target<=k){n.onFalse='stop';delete n.target;}});}render();}
  if(b.dataset.opRun){b.disabled=true;notice();const r=await api(b.dataset.opRun+'/run',{});selectedRun=r.id;view='runs';await refresh();}
  if(b.dataset.opToggle){await api('schedules/'+b.dataset.opToggle+'/toggle',{});await refresh();}
  if(b.dataset.opDuplicate){await api(b.dataset.opDuplicate+'/duplicate',{});await refresh();notice('Copia creada.');}
  if(b.dataset.opDelete&&confirm('¿Borrar este elemento? No se puede deshacer.')){await api(b.dataset.opDelete+'/delete',{});await refresh();notice('Borrado.');}
  if(b.dataset.flowApprove){b.disabled=true;await api(`runs/${b.dataset.flowApprove}/${b.dataset.allow==='true'?'approve':'reject'}`,{});await refresh();}
 }catch(err){notice(err.message);b.disabled=false;}
});
document.addEventListener('submit',async e=>{
 if(!['workflow-form','operation-form'].includes(e.target.id))return;e.preventDefault();const b=e.submitter;b.disabled=true;
 try{
  if(e.target.id==='workflow-form'){captureFlow();await api('workflows',flowDraft);flowDraft=null;}
  else {const f=e.target,body=Object.fromEntries(new FormData(f));if(f.dataset.id)body.id=f.dataset.id;if(f.dataset.kind==='schedules'){body.nextAt=new Date(body.date).toISOString();[body.targetKind,body.targetId]=body.target.split(':');delete body.target;}await api(f.dataset.kind,body);}
  await refresh();notice('Guardado.');
 }catch(err){notice(err.message);b.disabled=false;}
});

var accountUsage = {};
function usageHtml(id){
 const usage=accountUsage?.[id];
 if(id==='demo')return '';
 if(!usage)return '<p class="tiny">Consultando uso…</p>';
 if(!usage.windows?.length)return `<p class="tiny">${escape(usage.error||'El proveedor no informó límites.')}</p>`;
 return usage.windows.map(w=>`<div class="quota-row"><div><span>${escape(w.label||(w.minutes===300?'5 horas':w.minutes===10080?'Semanal':w.minutes?`${w.minutes} minutos`:'Límite del plan'))}</span><strong>${escape(w.usedPercent)}% usado</strong></div><meter min="0" max="100" value="${Number(w.usedPercent)||0}" aria-label="Porcentaje consumido"></meter><small>${Math.round(Math.max(0,100-w.usedPercent)*100)/100}% disponible${w.resetsAt?` · Reinicio ${new Date(w.resetsAt).toLocaleString('es-AR',{timeZone:'America/Argentina/Buenos_Aires',day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false})}`:''}</small></div>`).join('')+`<p class="tiny">Consultado ${new Date(usage.checkedAt).toLocaleTimeString('es-AR',{timeZone:'America/Argentina/Buenos_Aires',hour12:false})} · Buenos Aires</p>`;
}
function renderAccounts(){
 $('#account-indicators').innerHTML=connectedProviders().map(p=>`<div class="account-wrap"><button class="account-indicator ${p.accountState==='connected'?'connected':'disconnected'}" data-view="providers" aria-label="${escape(p.accountLabel||p.name)}">${providerIcons[p.id]||`<span aria-hidden="true">${escape(p.name?.slice(0,1)||'•')}</span>`}</button><div class="account-popover"><strong>${escape(p.id==='claude'?'Claude':p.id==='kimi'?'Kimi':p.id==='codex'?'ChatGPT':p.name)}</strong><p class="tiny">${escape(!p.installed?'No instalado':p.accountLabel||'Sesión no comprobada')}</p>${usageHtml(p.id)}</div></div>`).join('');
}
async function loadUsage(){try{accountUsage=await api('usage');renderAccounts();document.querySelectorAll('[data-usage-card]').forEach(el=>el.innerHTML=usageHtml(el.dataset.usageCard));}catch{accountUsage={};}}
setInterval(()=>{if(document.visibilityState!=='hidden')loadUsage();},300000);

async function loadBrowser(id){
 try{
 const b=await api(`runs/${id}/browser`);const panel=$('#run-browser');if(!panel||panel.dataset.browserRun!==id)return;
 panel.innerHTML=`<div class="browser-toolbar"><strong>◉ Navegador visual</strong><span>${escape(b.agent||'Esperando al agente')}</span>${b.open?`<button class="quiet" data-browser-close="${id}">Cerrar navegador</button>`:''}</div><div class="browser-address">${escape(b.url||'El agente todavía no abrió una página.')}</div>${b.pending?`<div class="browser-approval"><h3>El agente necesita tu autorización</h3><p>Revisá el destino y la acción antes de continuar. Autorizar puede enviar datos o producir cambios en el sitio.</p><pre>${escape(JSON.stringify(b.pending.action,null,2))}</pre><button class="primary" data-browser-decision="${b.pending.id}" data-run="${id}" data-allow="true">Autorizar esta acción</button> <button class="secondary" data-browser-decision="${b.pending.id}" data-run="${id}" data-allow="false">Rechazar</button></div>`:''}${b.image?`<a href="data:image/jpeg;base64,${b.image}" download="navegador.jpg"><img class="browser-shot" src="data:image/jpeg;base64,${b.image}" alt="Última captura del navegador del equipo"></a>`:'<div class="browser-empty">Las capturas aparecerán después de la primera acción.</div>'}<details class="browser-log" ${b.pending?'':'open'}><summary>Registro de acciones (${b.history.length})</summary>${b.history.map(h=>`<p><time>${new Date(h.at).toLocaleTimeString('es-AR',{hour12:false,timeZone:'America/Argentina/Buenos_Aires'})}</time> <b>${escape(h.agent)}</b> · ${escape(h.text)}</p>`).join('')}</details>`;
 }catch(e){const panel=$('#run-browser');if(panel?.dataset.browserRun===id)panel.textContent='No se pudo consultar el navegador. '+e.message;}
}

function browserConnectionHtml(){return `<section class="card browser-connection"><h2>Chromium dentro del MVP</h2><p>Navegá e iniciá sesión sin instalar extensiones. Tiene un perfil propio; las sesiones de Firefox no se importan. Los agentes sólo acceden a los sitios que autorices en su equipo.</p><button class="primary" data-view="internal">Abrir navegador interno</button></section><section class="card browser-connection"><h2>Tu navegador y tus sesiones</h2><p>Usá las aplicaciones donde ya iniciaste sesión. Instalá la extensión en Chrome, Edge o Brave y compartí las pestañas que elijas. No se copian cookies ni contraseñas al MVP.</p><div id="browser-connection-state">Comprobando conexión…</div><ol><li><a href="/api/browser-extension.zip" download>Descargar extensión local</a> y extraer el ZIP.</li><li>En la página de extensiones de tu navegador, activar Modo desarrollador → Cargar descomprimida → elegir la carpeta extraída.</li><li>Generar un código aquí y pegarlo en la extensión.</li><li>Abrir el sitio deseado, pulsar la extensión y elegir «Compartir esta pestaña HTTPS».</li><li>En Equipos → Sitios permitidos, elegir «Mis pestañas compartidas» y los sitios.</li></ol><p class="provider-note">La extensión solicita el permiso de depuración de Chrome para capturar y operar las pestañas compartidas. Chrome muestra un aviso mientras las controla. No compartas pestañas con contraseñas o información que no quieras enviar a tus proveedores de IA.</p><button class="primary" data-browser-pair>Generar código de conexión</button> <button class="secondary" data-browser-refresh>Actualizar conexión</button> <button class="quiet" data-browser-revoke>Revocar conexión</button><div id="browser-pair-code"></div></section>`;}
async function loadBrowserConnection(){try{const b=await api('browser-connection');const el=$('#browser-connection-state');if(el)el.innerHTML=`<p><strong>${b.connected?'● Navegador conectado':'○ Extensión sin conexión activa'}</strong></p><p>${b.tabs.length?b.tabs.map(t=>escape(t.origin)).join('<br>'):'Todavía no hay pestañas compartidas.'}</p>`;}catch(e){notice(e.message);}}
let accessTeamId;
async function showBrowserAccess(id){const t=state.teams.find(t=>t.id===id);if(!t)throw Error('Equipo no encontrado.');accessTeamId=id;const b=await api('browser-connection');$('#access-team-name').textContent=t.name;const f=$('#browser-access-form');f.elements.mode.value=t.browserAccess?.mode||'isolated';f.elements.sites.value=(t.browserAccess?.sites||[]).join('\n');$('#access-error').textContent='';$('#shared-sites').innerHTML=`<p>Sitios compartidos desde tu navegador:</p>${[...new Set(b.tabs.map(t=>t.origin))].map(site=>`<button type="button" class="secondary" data-add-site="${escape(site)}">＋ ${escape(site)}</button>`).join('')||'<p class="tiny">Compartí una pestaña desde la extensión para verla aquí. También podés escribir su dirección.</p>'}`;$('#browser-access-dialog').showModal();}
$('#close-browser-access').onclick=()=>$('#browser-access-dialog').close();
$('#browser-access-form').onsubmit=async e=>{e.preventDefault();const f=e.target;e.submitter.disabled=true;try{await api(`teams/${accessTeamId}/browser-access`,{mode:f.elements.mode.value,sites:f.elements.sites.value.split(/\n/).map(s=>s.trim()).filter(Boolean)});state=await api('state');$('#browser-access-dialog').close();render();notice('Permisos del equipo guardados.');}catch(e){$('#access-error').textContent=e.message;}finally{e.submitter.disabled=false;}};
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;try{
 if(b.dataset.browserAccess)await showBrowserAccess(b.dataset.browserAccess);
 if(b.dataset.addSite){const f=$('#browser-access-form');f.elements.sites.value=[...new Set([...f.elements.sites.value.split(/\n/).filter(Boolean),b.dataset.addSite])].join('\n');f.elements.mode.value='existing';}
 if(b.hasAttribute('data-browser-pair')){const p=await api('browser-connection/pair',{});$('#browser-pair-code').innerHTML=`<label>Código temporal (vence en cinco minutos)<input readonly value="${escape(p.code)}" aria-label="Código de conexión"></label><p class="tiny">Pegalo sólo en la extensión local. No lo compartas.</p>`;}
 if(b.hasAttribute('data-browser-refresh'))await loadBrowserConnection();
 if(b.hasAttribute('data-browser-revoke')){await api('browser-connection/revoke',{});$('#browser-pair-code').replaceChildren();await loadBrowserConnection();notice('Conexión revocada. Los equipos ya no pueden operar tus pestañas.');}
}catch(e){notice(e.message);}});

document.addEventListener('change',e=>{if(e.target.id==='avatar-collection'){$('.art-grid').innerHTML=avatarGrid(e.target.value,$('#create-agent-form').elements.avatar.value);}if(e.target.matches('.agent-fields select[name="avatar"]'))e.target.closest('.agent-avatar-choice').querySelector('.agent-avatar-preview').innerHTML=agentAvatar({avatar:e.target.value});});
document.addEventListener('click',e=>{const b=e.target.closest('[data-art-avatar]');if(!b)return;$('#create-agent-form').elements.avatar.value=b.dataset.artAvatar;$('.avatar-art-preview').innerHTML=agentAvatar({avatar:b.dataset.artAvatar});document.querySelectorAll('[data-art-avatar]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));});

let internalBusy=false,internalSnapshot=null;
function renderInternalBrowser(){
 $('#content').innerHTML=heading('Navegador interno','Chromium con un perfil propio. Iniciá sesión vos y luego elegí los sitios permitidos de tu equipo.')+`<section class="card"><form id="internal-address-form" class="row"><label>Dirección de la página<input name="url" type="url" placeholder="https://tu-aplicacion.com" required></label><button class="primary">Abrir página</button></form><p class="tiny">El perfil conserva las sesiones en esta computadora. Este panel es para vos: no envía contenido a una IA. Al ejecutar un equipo autorizado, sí se compartirán las capturas y el texto del sitio con sus proveedores.</p><div class="browser-toolbar"><button data-internal-action="inspect">Actualizar vista</button><button data-internal-action="scroll" data-direction="up">↑ Subir</button><button data-internal-action="scroll" data-direction="down">↓ Bajar</button><button data-internal-key="Tab">Tab</button><button data-internal-key="Enter">Enter</button><button data-internal-key="Backspace">Borrar</button><button data-internal-key="Control+A">Seleccionar todo</button></div><p id="internal-status" role="status">Abrí una página para comenzar.</p><div id="internal-viewport"></div><form id="internal-type-form" class="row"><label>Escribir en el campo seleccionado<input name="text" type="password" autocomplete="off" placeholder="Primero hacé clic en un campo de la página"></label><button class="secondary">Escribir en la página</button></form><p class="tiny">Hacé clic en la captura para interactuar. El texto se borra de este control al enviarlo y no se agrega a los registros. No se omiten advertencias de seguridad. Algunas aplicaciones pueden impedir el inicio de sesión en navegadores automatizados.</p><button class="secondary" data-view="teams">Elegir equipo y sitios permitidos</button></section>`;
 if(internalSnapshot)showInternalSnapshot(internalSnapshot);
}
function showInternalSnapshot(s){internalSnapshot=s;const el=$('#internal-viewport');if(!el)return;el.innerHTML=`<img id="internal-screen" src="data:image/jpeg;base64,${s.screenshot}" alt="Página de Chromium interno; hacé clic para interactuar" draggable="false">`;$('#internal-status').textContent=s.url;}
async function internalAction(action,args={}){if(internalBusy)return;internalBusy=true;const status=$('#internal-status');if(status)status.textContent='Actualizando navegador…';try{showInternalSnapshot(await api('internal-browser',{action,...args}));}catch(e){if(/Timeout|timeout/.test(e.message)){try{showInternalSnapshot(await api('internal-browser',{action:'inspect'}));}catch{if($('#internal-status'))$('#internal-status').textContent='La página está tardando en responder. Probá Actualizar vista.';}}else if($('#internal-status'))$('#internal-status').textContent=e.message.replace(/\x1b\[[0-9;]*m/g,'');}finally{internalBusy=false;}}
document.addEventListener('submit',async e=>{if(e.target.id==='internal-address-form'){e.preventDefault();await internalAction('open',{url:e.target.elements.url.value});}if(e.target.id==='internal-type-form'){e.preventDefault();const text=e.target.elements.text.value;e.target.elements.text.value='';await internalAction('type',{text});}});
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(b?.dataset.internalAction)await internalAction(b.dataset.internalAction,{direction:b.dataset.direction});if(b?.dataset.internalKey)await internalAction('key',{key:b.dataset.internalKey});if(e.target.id==='internal-screen'){const r=e.target.getBoundingClientRect();await internalAction('click',{x:(e.clientX-r.left)*1180/r.width,y:(e.clientY-r.top)*760/r.height});}});

document.addEventListener('submit',async e=>{if(e.target.id!=='agent-chat-form')return;e.preventDefault();const form=e.target,button=e.submitter;button.disabled=true;try{const run=await api(`teams/${selectedTeam}/agents/${selectedAgent}/chat`,{message:form.elements.message.value});chatMessages.push(run);render();}catch(error){notice(error.message);button.disabled=false;}});

document.addEventListener('submit',async e=>{if(e.target.id!=='team-chat-form')return;e.preventDefault();const f=e.target,b=e.submitter;b.disabled=true;try{const team=state.teams.find(t=>t.id===selectedTeam), message=f.elements.message.value, mentions=team.agents.map((a,i)=>({i,name:a.name})).filter(a=>message.toLocaleLowerCase().includes('@'+a.name.toLocaleLowerCase()));if(mentions.length>1)throw Error('Indicá un solo destinatario con @ o elegilo en la lista.');teamChatRecipient=mentions.length?mentions[0].i:Number(f.elements.recipient.value);const run=await api(`teams/${selectedTeam}/chat`,{message,index:teamChatRecipient});teamChatMessages.push(run);notice();render();}catch(error){notice(error.message);b.disabled=false;}});

document.addEventListener('change',e=>{if(e.target.id==='team-chat-recipient')teamChatRecipient=Number(e.target.value);});

async function renderConnectors(){
 const host=$('#content');host.innerHTML=heading('Conectores','Herramientas y cuentas para tus agentes.')+'<p class="provider-note">Cargando…</p>';
 try{
  const [items,status,grants]=await Promise.all([api('connectors'),api('google/status'),Promise.all(state.teams.map(async t=>({id:t.id,services:(await api(`teams/${t.id}/google-access`)).services})))]);if(view!=='connectors')return;
  host.innerHTML=heading('Conectores','Cuentas y permisos por equipo.')+`<div class="banner"><div><h2>Google · acceso de lectura</h2><p>${status.connected?'Conectada: '+escape(status.email||'cuenta Google'):status.pending?'Esperando autorización en Google':'Sin conexión activa'}.${status.error?' '+escape(status.error):''} ${status.persisted?'La conexión está guardada en el llavero del sistema.':'La conexión todavía no está guardada para el próximo inicio.'} Los correos y eventos consultados se envían al proveedor de IA que use el agente.</p><p>Requiere un cliente OAuth de escritorio y las APIs habilitadas en Google Cloud. El acceso se limita a búsqueda y lectura de texto de Gmail y eventos del calendario principal.</p></div></div><section class="card google-settings"><h2>${status.connected?'Cuenta conectada':'Conectar una cuenta Google'}</h2>${status.connected?`<p class="provider-note">Servicios autorizados: ${status.services.map(escape).join(', ')}</p><button class="secondary" data-google-disconnect>Desconectar</button>`:`<form id="google-connect-form"><label>Archivo JSON del cliente OAuth de Google (opcional)<input type="file" name="clientFile" accept=".json,application/json"></label><label>ID de cliente OAuth<input name="clientId" required autocomplete="off" placeholder="…apps.googleusercontent.com"></label><label>Secreto de cliente de escritorio<input name="clientSecret" type="password" required autocomplete="off"></label><label><input type="checkbox" name="gmail" checked> Gmail · lectura</label><label><input type="checkbox" name="calendar" checked> Google Calendar · lectura</label><button class="primary">Preparar autorización</button></form><div id="google-auth-link"></div>`}</section><section class="card google-settings"><h2>Permisos por equipo</h2><p class="provider-note">Asigná únicamente los servicios que cada equipo necesita. Atlas usa los permisos de su propio equipo. Un cambio se aplica a las siguientes consultas, incluso durante una ejecución.</p>${state.teams.map(t=>{const g=grants.find(x=>x.id===t.id)?.services||[];return `<form class="google-grant" data-team="${t.id}"><strong>${escape(t.name)}</strong><label><input type="checkbox" name="gmail" ${g.includes('gmail')?'checked':''}> Gmail</label><label><input type="checkbox" name="calendar" ${g.includes('calendar')?'checked':''}> Calendar</label><button class="secondary">Guardar permisos</button></form>`}).join('')||'<p class="tiny">Creá un equipo para asignar permisos.</p>'}</section><div class="grid">${items.filter(c=>!['gmail','google-calendar'].includes(c.id)).map(c=>`<article class="card"><span class="badge">EN DESARROLLO · ${escape(c.transport.toUpperCase())}</span><h3>${escape(c.name)}</h3><p class="provider-note">${escape(c.description)}</p></article>`).join('')}</div>`;
 }catch(e){if(view==='connectors')host.innerHTML=heading('Conectores','No se pudo cargar.')+`<p class="error">${escape(e.message)}</p>`;}
}
document.addEventListener('submit',async e=>{
 if(e.target.id==='google-connect-form'){e.preventDefault();const f=e.target,b=e.submitter;b.disabled=true;try{const services=['gmail','calendar'].filter(n=>f.elements[n].checked),data=await api('google/start',{clientId:f.elements.clientId.value.trim(),clientSecret:f.elements.clientSecret.value,services});f.elements.clientSecret.value='';$('#google-auth-link').innerHTML=`<p>Abrí Google, elegí tu cuenta y aceptá los permisos solicitados. Después volvé y actualizá esta sección.</p><a class="secondary google-auth" href="${escape(data.url)}" target="_blank" rel="noopener noreferrer">Abrir autorización de Google</a> <button class="secondary" data-google-refresh>Actualizar estado</button>`;}catch(err){notice(err.message);}finally{b.disabled=false;}}
 if(e.target.classList.contains('google-grant')){e.preventDefault();const f=e.target,b=e.submitter;b.disabled=true;try{await api(`teams/${f.dataset.team}/google-access`,{services:['gmail','calendar'].filter(n=>f.elements[n].checked)});notice('Permisos guardados.');}catch(err){notice(err.message);}finally{b.disabled=false;}}
});
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;try{if(b.hasAttribute('data-google-refresh'))await renderConnectors();if(b.hasAttribute('data-google-disconnect')){await api('google/disconnect',{});await renderConnectors();}}catch(err){notice(err.message);}});

document.addEventListener('change',async e=>{if(e.target.name!=='clientFile'||!e.target.closest('#google-connect-form'))return;try{const file=e.target.files?.[0];if(!file)return;if(file.size>30000)throw Error('El archivo es demasiado grande.');const data=JSON.parse(await file.text()),client=data.installed;if(!client||typeof client.client_id!=='string'||typeof client.client_secret!=='string')throw Error('Elegí el JSON de un cliente OAuth de escritorio.');const form=e.target.form;form.elements.clientId.value=client.client_id;form.elements.clientSecret.value=client.client_secret;notice('Datos del cliente cargados. Prepará la autorización.');}catch(err){notice(err.message||'No se pudo leer el archivo.');}});

let whatsappPolling=false;
async function renderWhatsApp(){
 const host=$('#content');try{
  const status=await api('whatsapp/status');if(view!=='whatsapp')return;
  let extra='';
  if(status.enabled&&status.status!=='connected'){
   const pair=await api('whatsapp/qr');if(view!=='whatsapp')return;
   if(pair.qrSvg)extra=`<p>Escaneá este código desde Dispositivos vinculados en WhatsApp.</p><img alt="Código QR para vincular WhatsApp" width="240" height="240" src="data:image/svg+xml,${encodeURIComponent(pair.qrSvg)}">`;
   else if(pair.code)extra=`<p>Código de emparejamiento: <strong>${escape(pair.code)}</strong></p>`;
   else extra='<p>Esperando el código de vinculación…</p>';
  }
  if(status.enabled&&status.status==='connected'&&status.mode==='dedicated'&&!status.owner){const code=await api('whatsapp/owner-code');extra=`<p>Desde el teléfono que usás para darle órdenes a Atlas, enviá este código al número de WhatsApp vinculado: <strong>${escape(code.code)}</strong>. Vence en 10 minutos.</p>`;}
  const statusLabels={connected:'Conectado',connecting:'Conectando',disconnected:'Desconectado',logged_out:'Sesión cerrada desde el teléfono',forbidden:'Acceso rechazado por WhatsApp',unavailable:'No disponible en este sistema',credentials_error:'Error al guardar la sesión',pairing_error:'No se pudo generar el código',unlinked:'Sin vincular'};
  host.innerHTML=heading('WhatsApp','Conversá con tu agente principal desde tu teléfono.')+`<section class="card"><h2>${status.enabled?'Estado: '+escape(statusLabels[status.status]||status.status):'Vincular WhatsApp'}</h2><p>Esta función es experimental y usa un cliente no oficial. Tu cuenta podría ser bloqueada; recomendamos usar un número dedicado. Si la computadora está suspendida, no puede responder.</p>${!status.enabled?`<form id="whatsapp-link-form"><label>Modo<select name="mode"><option value="dedicated">Número dedicado (recomendado)</option><option value="own">Mi número personal</option></select></label><label>Vincular con<select name="method"><option value="qr">Código QR</option><option value="code">Código de emparejamiento</option></select></label><label id="whatsapp-phone-field" hidden>Número de WhatsApp que usará Tropa<input name="phone" inputmode="numeric" autocomplete="tel" placeholder="Ej.: 5491112345678"><span class="provider-note">Ingresá el número de la cuenta que vas a vincular a Tropa, con código de país y solo dígitos, sin +, espacios ni guiones. El teléfono autorizado para hablar con Atlas se registra después.</span></label><label><input type="checkbox" name="risk" required> Entiendo el riesgo y acepto vincular una cuenta experimental.</label><button class="primary">Vincular</button></form>`:`${extra}${['disconnected','logged_out','forbidden','unavailable','pairing_error'].includes(status.status)?'<button class="secondary" data-whatsapp-retry>Reintentar</button>':''}${status.owner?`<p>Teléfono autorizado: ${escape(status.owner.masked)}</p>`:''}<label><input type="checkbox" data-whatsapp-progress ${status.progress?'checked':''}> Avisos de delegación</label><label><input type="checkbox" data-whatsapp-autostart ${status.autostart?'checked':''}> Iniciar Tropa con el sistema</label><p class="tiny">La vinculación se guarda en este equipo.</p><button class="secondary" data-whatsapp-unlink>Desvincular</button>`}</section>`;
  whatsappPolling=status.enabled&&(status.status!=='connected'||(status.mode==='dedicated'&&!status.owner));
 }catch(e){if(view==='whatsapp')host.innerHTML=heading('WhatsApp','No se pudo cargar.')+`<p class="error">${escape(e.message)}</p>`;}
}
document.addEventListener('submit',async e=>{if(e.target.id!=='whatsapp-link-form')return;e.preventDefault();const f=e.target,b=e.submitter;b.disabled=true;try{await api('whatsapp/link',{mode:f.elements.mode.value,method:f.elements.method.value,phone:f.elements.phone.value.trim(),acceptedRisk:f.elements.risk.checked});await renderWhatsApp();}catch(err){notice(err.message);b.disabled=false;}});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-whatsapp-unlink], [data-whatsapp-retry]');if(!b)return;try{if(b.hasAttribute('data-whatsapp-retry'))await api('whatsapp/retry',{});else {await api('whatsapp/unlink',{});whatsappPolling=false;}await renderWhatsApp();}catch(err){notice(err.message);}});
document.addEventListener('change',async e=>{if(!e.target.matches('[data-whatsapp-progress], [data-whatsapp-autostart]'))return;const input=e.target;try{await api('whatsapp/settings',input.matches('[data-whatsapp-progress]')?{progress:input.checked}:{autostart:input.checked});}catch(err){input.checked=!input.checked;notice(err.message);}});
setInterval(()=>{if(view==='whatsapp'&&whatsappPolling&&document.visibilityState!=='hidden')renderWhatsApp();},1000);

document.addEventListener('change',e=>{if(e.target.name!=='method'||e.target.form?.id!=='whatsapp-link-form')return;const phone=e.target.form.elements.phone,show=e.target.value==='code';$('#whatsapp-phone-field').hidden=!show;phone.required=show;});

let updateState=null, updateChecking=false;
async function checkForUpdates(){
  if(updateChecking)return; updateChecking=true;
  try { updateState=await api('updates'); }
  catch { updateState={error:'No se pudo comprobar la versión. Revisá tu conexión e intentá nuevamente.'}; }
  finally { updateChecking=false; const button=document.querySelector('.section-nav [data-view="updates"]');if(button)button.textContent=updateState?.available?'↻ Actualización disponible':'↻ Actualizaciones';if(view==='updates')renderUpdates(); }
}
function renderUpdates(){
  const host=$('#content');
  const content=!updateState?'Comprobando actualizaciones…':updateState.error?escape(updateState.error):updateState.available?`Nueva versión disponible: <strong>${escape(updateState.latestVersion)}</strong>.`:'Tenés la última versión disponible.';
  host.innerHTML=heading('Actualizaciones','Consultá la versión de Tropa instalada.')+`<section class="card google-settings"><h2>Versión ${escape(updateState?.currentVersion||'—')}</h2><p>${content}</p>${updateState?.downloadUrl?`<a class="primary" href="${escape(updateState.downloadUrl)}" target="_blank" rel="noopener">Descargar actualización</a><p class="tiny">Cerrá Tropa antes de instalar la nueva versión. Tus datos permanecen en este equipo.</p>`:updateState?.available?'<p class="tiny">Todavía no hay instalador disponible para este sistema.</p>':''}<button class="secondary" data-check-updates ${updateChecking?'disabled':''}>Buscar actualizaciones</button></section>`;
}
document.addEventListener('click',e=>{if(e.target.closest('[data-check-updates]'))checkForUpdates();});
checkForUpdates();

function syncLocalProvider(select){
 if(!select)return;
 const container=select.closest('.agent-fields')||select.form,p=connections.find(x=>x.id===select.value),list=select.id==='agent-provider'?$('#local-models'):null;
 if(list)list.innerHTML=(p?.models||[]).map(m=>`<option value="${escape(m)}"></option>`).join('');
 const local=['ollama','lmstudio'].includes(select.value);
 for(const name of ['tools','browser']){const input=container.querySelector(`[name="${name}"]`);if(input){input.disabled=local;if(local)input.checked=false;}}
}
document.addEventListener('change',e=>{if(e.target.id==='agent-provider'||e.target.matches('.agent-fields [name="provider"]'))syncLocalProvider(e.target);});
let phoneInvite=null;
const phonePlatform={ios:'iPhone',android:'Android',other:'Teléfono'};
async function renderPhones(){
 const host=$('#content');
 try{
  const s=await api('mobile/status');if(view!=='phones')return;
  const inv=s.invite;if(!inv)phoneInvite=null;
  let pairing='';
  if(inv?.pending){const c=inv.pending.code;pairing=`<section class="card phone-confirm"><h2>¿Coinciden los códigos?</h2><p>${escape(inv.pending.name)} (${phonePlatform[inv.pending.platform]||'Teléfono'}) quiere vincularse. Confirmá solo si el teléfono muestra exactamente este código:</p><p class="phone-code">${escape(c.slice(0,3))} ${escape(c.slice(3))}</p><button class="primary" data-phone-confirm="true">Sí, coincide</button> <button class="secondary" data-phone-confirm="false">No coincide</button></section>`;}
  else if(inv&&phoneInvite)pairing=`<section class="card phone-qr"><h2>Escaneá con la app Tropa</h2><img alt="Código QR para vincular un teléfono" width="240" height="240" src="data:image/svg+xml,${encodeURIComponent(phoneInvite.qrSvg)}"><p class="tiny">Un solo uso. Vence a las ${new Date(inv.expiresAt).toLocaleTimeString('es-AR',{hour:'2-digit',minute:'2-digit'})}.</p><button class="quiet" data-phone-cancel>Cancelar</button></section>`;
  const rows=s.devices.map(d=>`<div class="device-row"><span class="device-dot ${d.online?'on':''}" aria-hidden="true"></span><div><p><strong>${escape(d.name)}</strong> · ${phonePlatform[d.platform]||'Teléfono'}</p><small>${d.online?'Conectado ahora':d.lastSeen?'Última conexión: '+new Date(d.lastSeen).toLocaleString('es-AR'):'Todavía no se conectó'}</small></div><button class="quiet" data-phone-revoke="${escape(d.id)}">Desvincular</button></div>`).join('');
  host.innerHTML=heading('Teléfonos','Usá Tropa desde tu teléfono por internet. Todo viaja cifrado de extremo a extremo y tu compu tiene que estar encendida.')
   +`<section class="card"><h2>Relay</h2><p>${s.relayUrl?`${s.connected?'● Conectado':'○ Sin conexión'} · <span class="relay-url">${escape(s.relayUrl)}</span>`:'Todavía no configuraste la dirección del relay.'}</p><form id="relay-form" class="inline-form"><input name="relayUrl" aria-label="Dirección del relay" placeholder="wss://tropa.galateasoftware.com.ar/relay" value="${escape(s.relayUrl||'')}"><button class="secondary">Guardar</button></form></section>`
   +pairing
   +`<section class="card"><h2>Teléfonos vinculados</h2>${rows||'<p class="tiny">Ninguno todavía.</p>'}<button class="primary" data-phone-invite ${s.relayUrl?'':'disabled'}>＋ Vincular un teléfono</button><p class="provider-note">Desde el teléfono podés chatear con tus agentes, seguir tareas y flujos, aprobar acciones y descargar archivos. Podés pedirle a Atlas que cree agentes o equipos. Para editar equipos y cambiar permisos, usá el escritorio.</p></section>`;
 }catch(e){host.innerHTML=heading('Teléfonos','No se pudo cargar.')+`<p class="error">${escape(e.message)}</p>`;}
}
setInterval(()=>{if(view==='phones'&&document.visibilityState!=='hidden'&&!document.activeElement?.closest?.('#relay-form'))renderPhones();},1500);
document.addEventListener('click',async e=>{
 const b=e.target.closest('button');if(!b)return;
 try{
  if(b.hasAttribute('data-phone-invite')){b.disabled=true;phoneInvite=await api('mobile/invite',{});await renderPhones();}
  if(b.dataset.phoneConfirm){b.disabled=true;await api('mobile/confirm',{accept:b.dataset.phoneConfirm==='true'});phoneInvite=null;notice(b.dataset.phoneConfirm==='true'?'Teléfono vinculado.':'Emparejamiento rechazado.');await renderPhones();}
  if(b.hasAttribute('data-phone-cancel')){phoneInvite=null;await renderPhones();}
  if(b.dataset.phoneRevoke&&confirm('¿Desvincular este teléfono? Pierde el acceso al instante.')){await api(`mobile/devices/${b.dataset.phoneRevoke}/revoke`,{});notice('Teléfono desvinculado.');await renderPhones();}
 }catch(err){notice(err.message);b.disabled=false;}
});
document.addEventListener('submit',async e=>{
 if(e.target.id!=='relay-form')return;e.preventDefault();
 try{await api('mobile/settings',{relayUrl:e.target.elements.relayUrl.value});document.activeElement?.blur?.();notice('Guardado.');await renderPhones();}catch(err){notice(err.message);}
});
